917	std::vector<SegmentTask::Ptr> CollectionImpl::build_compact_task(
918	    const CollectionSchema::Ptr &schema,
919	    const std::vector<Segment::Ptr> &segments, int concurrency,
920	    const IndexFilter::Ptr filter) {
921	  std::vector<SegmentTask::Ptr> tasks;
922	  if (segments.empty()) return tasks;
923	
924	  bool rebuild = false;
925	  size_t current_doc_count = 0;
926	  size_t current_actual_doc_count = 0;
927	  for (auto &segment : segments) {
928	    current_doc_count += segment->doc_count();
929	    current_actual_doc_count += segment->doc_count(filter);
930	  }
931	  if (current_actual_doc_count <
932	      current_doc_count * (1 - COMPACT_DELETE_RATIO_THRESHOLD)) {
933	    // if delete ratio is large enough, rebuild
934	    rebuild = true;
935	  }
936	
937	  auto max_doc_count_per_segment = schema->max_doc_count_per_segment();
938	
939	  std::vector<Segment::Ptr> current_group;
940	  current_doc_count = 0;
941	  current_actual_doc_count = 0;
942	
943	  for (const auto &seg : segments) {
944	    uint64_t doc_count = seg->doc_count();
945	    uint64_t actual_doc_count = seg->doc_count(filter);
946	
947	    if (!current_group.empty()) {
948	      SegmentTask::Ptr task;
949	      bool skip_task{false};
950	      if (rebuild) {
951	        if (current_actual_doc_count + actual_doc_count >
952	            max_doc_count_per_segment) {
953	          // only create SegmentCompactTask when rebuild=true
954	          task = SegmentTask::CreateCompactTask(
955	              CompactTask{path_, schema, current_group,
956	                          allocate_segment_id_for_tmp_segment(), filter,
957	                          !options_.enable_mmap_, concurrency});
958	        }
959	      } else {
960	        if (current_doc_count + doc_count > max_doc_count_per_segment) {
961	          // check current_group size
962	          if (current_group.size() == 1) {
963	            task =
964	                SegmentTask::CreateCreateVectorIndexTask(CreateVectorIndexTask{
965	                    current_group[0], "", nullptr, concurrency});
966	            skip_task = current_group[0]->all_vector_index_ready();
967	          } else {
968	            task = SegmentTask::CreateCompactTask(
969	                CompactTask{path_, schema, current_group,
970	                            allocate_segment_id_for_tmp_segment(), nullptr,
971	                            !options_.enable_mmap_, concurrency});
972	          }
973	        }
974	      }
975	
976	      if (task) {
977	        current_group.clear();
978	        current_doc_count = 0;
979	        current_actual_doc_count = 0;
980	        if (!skip_task) {
981	          tasks.push_back(task);
982	        }
983	      }
984	    }
985	
986	    current_group.push_back(seg);
987	    current_doc_count += doc_count;
988	    current_actual_doc_count += actual_doc_count;
989	  }
990	
991	  if (current_group.size() > 0) {
992	    SegmentTask::Ptr task;
993	    if (current_group.size() == 1 && !rebuild) {
994	      task = SegmentTask::CreateCreateVectorIndexTask(
995	          CreateVectorIndexTask{current_group[0], "", nullptr, concurrency});
996	    } else {
997	      task = SegmentTask::CreateCompactTask(CompactTask{
998	          path_, schema, current_group, allocate_segment_id_for_tmp_segment(),
999	          rebuild ? filter : nullptr, !options_.enable_mmap_, concurrency});
1000	    }
1001	    tasks.push_back(task);
1002	  }
1003	
1004	  return tasks;
1005	}
