2054	Segment::Ptr CollectionImpl::local_segment_by_doc_id(
2055	    uint64_t doc_id, const std::vector<Segment::Ptr> &segments) const {
2056	  size_t left = 0;
2057	  size_t right = segments.size();
2058	
2059	  while (left < right) {
2060	    size_t mid = left + (right - left) / 2;
2061	    uint64_t min_id = segments[mid]->meta()->min_doc_id();
2062	    uint64_t max_id = segments[mid]->meta()->max_doc_id();
2063	
2064	    if (doc_id < min_id) {
2065	      right = mid;
2066	    } else if (doc_id > max_id) {
2067	      left = mid + 1;
2068	    } else {
2069	      return segments[mid];
2070	    }
2071	  }
2072	
2073	  return nullptr;
2074	}
