  for (const auto segment_doc_id : segment_doc_ids) {
    auto it = std::upper_bound(chunk_offsets_.begin(), chunk_offsets_.end(),
                               segment_doc_id);
    if (it == chunk_offsets_.begin()) {
      LOG_ERROR("Segment doc ID %d is out of bounds", segment_doc_id);
