51	Status SegmentHelper::Execute(SegmentTask::Ptr &task) {
52	  auto &task_info = task->task_info();
53	  Status s;
54	  if (std::holds_alternative<CompactTask>(task_info)) {
55	    auto &compact_task = std::get<CompactTask>(task_info);
56	    s = ExecuteCompactTask(compact_task);
57	  } else if (std::holds_alternative<CreateVectorIndexTask>(task_info)) {
58	    auto &create_index_task = std::get<CreateVectorIndexTask>(task_info);
59	    s = ExecuteCreateVectorIndexTask(create_index_task);
60	  } else if (std::holds_alternative<CreateScalarIndexTask>(task_info)) {
61	    auto &create_index_task = std::get<CreateScalarIndexTask>(task_info);
62	    s = ExecuteCreateScalarIndexTask(create_index_task);
63	  } else if (std::holds_alternative<DropVectorIndexTask>(task_info)) {
64	    auto &drop_index_task = std::get<DropVectorIndexTask>(task_info);
65	    s = ExecuteDropVectorIndexTask(drop_index_task);
66	  } else if (std::holds_alternative<DropScalarIndexTask>(task_info)) {
67	    auto &drop_index_task = std::get<DropScalarIndexTask>(task_info);
68	    s = ExecuteDropScalarIndexTask(drop_index_task);
69	  } else if (std::holds_alternative<CreateFtsIndexTask>(task_info)) {
70	    auto &fts_task = std::get<CreateFtsIndexTask>(task_info);
71	    s = fts_task.input_segment_->create_fts_index(
72	        fts_task.column_, fts_task.index_params_,
73	        &fts_task.output_segment_meta_, &fts_task.output_fts_indexer_);
74	  } else if (std::holds_alternative<DropFtsIndexTask>(task_info)) {
75	    auto &fts_task = std::get<DropFtsIndexTask>(task_info);
76	    s = fts_task.input_segment_->drop_fts_index(fts_task.column_,
77	                                                &fts_task.output_segment_meta_,
78	                                                &fts_task.output_fts_indexer_);
79	  } else {
80	    return Status::InvalidArgument("Unknown task type");
81	  }
82	  return s;
83	}
