86	 public:
87	  // Copies the bitmap so callers can keep using it (e.g. share with FTS
88	  // reduce).
89	  explicit RowIdFilter(const roaring::Roaring &delete_row_id_bitmap)
90	      : delete_row_id_bitmap_(delete_row_id_bitmap) {}
91	
92	  bool is_filtered(uint64_t id) const override {
93	    return delete_row_id_bitmap_.contains(id);
94	  }
95	
96	 private:
97	  roaring::Roaring delete_row_id_bitmap_;
98	};
