638	Status SegmentHelper::ReduceVectorIndex(
639	    const CollectionSchema::Ptr schema,
640	    const std::vector<Segment::Ptr> &input_segments,
641	    const std::string &output_segment_path, const IndexFilter::Ptr &filter,
642	    std::function<BlockID()> &block_id_generator, uint64_t min_doc_id,
643	    uint64_t max_doc_id, uint32_t doc_count, int concurrency,
644	    std::vector<BlockMeta> *output_block_metas) {
645	  Status s;
646	
647	  // vector
648	  auto vector_fields = schema->vector_fields();
649	  for (auto &field : vector_fields) {
650	    auto vector_index_params =
651	        std::dynamic_pointer_cast<VectorIndexParams>(field->index_params());
652	
653	    using FetchIndexersFn =
654	        std::vector<VectorColumnIndexer::Ptr> (Segment::*)(const std::string &)
655	            const;
656	    auto collect_merge_indexers = [&](FetchIndexersFn fetch) {
657	      std::vector<VectorColumnIndexer::Ptr> source_indexers;
658	      for (const auto &seg : input_segments) {
659	        auto seg_indexers = (seg.get()->*fetch)(field->name());
660	        source_indexers.insert(source_indexers.end(), seg_indexers.begin(),
661	                               seg_indexers.end());
662	      }
663	      return source_indexers;
664	    };
665	
666	    auto vector_block_id = block_id_generator();
667	    if (vector_index_params->quantize_type() == QuantizeType::UNDEFINED) {
668	      auto vector_index_path = FileHelper::MakeVectorIndexPath(
669	          output_segment_path, field->name(), vector_block_id);
670	
671	      s = MergeWithOptionalReuse(
672	          vector_index_path, *field,
673	          collect_merge_indexers(&Segment::get_vector_indexer), filter,
674	          concurrency, nullptr);
675	      CHECK_RETURN_STATUS(s);
676	
677	      BlockMeta new_block_meta;
678	      new_block_meta.set_id(vector_block_id);
679	      new_block_meta.set_type(BlockType::VECTOR_INDEX);
680	      new_block_meta.set_columns({field->name()});
681	      new_block_meta.set_min_doc_id(min_doc_id);
682	      new_block_meta.set_max_doc_id(max_doc_id);
683	      new_block_meta.set_doc_count(doc_count);
684	
685	      output_block_metas->push_back(new_block_meta);
686	    } else {
687	      auto vector_index_path = FileHelper::MakeVectorIndexPath(
688	          output_segment_path, field->name(), vector_block_id);
689	
690	      auto field_without_quantize = std::make_shared<FieldSchema>(*field);
691	      field_without_quantize->set_index_params(
692	          MakeDefaultVectorIndexParams(vector_index_params->metric_type()));
693	
694	      VectorColumnIndexer::Ptr vector_indexer;
695	      s = MergeWithOptionalReuse(
696	          vector_index_path, *field_without_quantize,
697	          collect_merge_indexers(&Segment::get_vector_indexer), filter,
698	          concurrency, &vector_indexer);
699	      CHECK_RETURN_STATUS(s);
700	
701	      // The training step (for RABITQ) and the subsequent quantize merge both
702	      // rely on the raw provider held by the flat indexer, so its Close() is
703	      // deferred until after the quantize indexer is written.
704	      core::IndexProvider::Pointer raw_vector_provider;
705	      if (vector_index_params->quantize_type() == QuantizeType::RABITQ) {
706	        raw_vector_provider = vector_indexer->create_index_provider();
707	      }
708	
709	      std::shared_ptr<FieldSchema> field_for_quantize;
710	      s = PrepareQuantizeField(*field, raw_vector_provider,
711	                               &field_for_quantize);
712	      CHECK_RETURN_STATUS(s);
713	
714	      BlockMeta new_block_meta;
715	      new_block_meta.set_id(vector_block_id);
716	      new_block_meta.set_type(BlockType::VECTOR_INDEX);
717	      new_block_meta.set_columns({field->name()});
718	      new_block_meta.set_min_doc_id(min_doc_id);
719	      new_block_meta.set_max_doc_id(max_doc_id);
720	      new_block_meta.set_doc_count(doc_count);
721	      output_block_metas->push_back(new_block_meta);
722	
723	      // create quantize index
724	      auto vector_quan_block_id = block_id_generator();
725	
726	      auto vector_quan_index_path = FileHelper::MakeQuantizeVectorIndexPath(
727	          output_segment_path, field->name(), vector_quan_block_id);
728	
729	      // RABITQ requires raw fp32 vectors as input, because re-encoding the
730	      // already-encoded quant indexers would produce garbage data. Other
731	      // types require the quantized vectors as input.
732	      auto quant_merge_sources =
733	          (vector_index_params->quantize_type() == QuantizeType::RABITQ)
734	              ? collect_merge_indexers(&Segment::get_vector_indexer)
735	              : collect_merge_indexers(&Segment::get_quant_vector_indexer);
736	
737	      s = MergeWithOptionalReuse(vector_quan_index_path, *field_for_quantize,
738	                                 quant_merge_sources, filter, concurrency,
739	                                 nullptr);
740	      CHECK_RETURN_STATUS(s);
741	
742	      s = vector_indexer->Close();
743	      CHECK_RETURN_STATUS(s);
744	
745	      new_block_meta.set_id(vector_quan_block_id);
746	      new_block_meta.set_type(BlockType::VECTOR_INDEX_QUANTIZE);
747	      new_block_meta.set_columns({field->name()});
748	      new_block_meta.set_min_doc_id(min_doc_id);
749	      new_block_meta.set_max_doc_id(max_doc_id);
750	      new_block_meta.set_doc_count(doc_count);
751	      output_block_metas->push_back(new_block_meta);
752	    }
753	  }
754	
755	  return Status::OK();
756	}
