852	Status SegmentHelper::PrepareQuantizeField(
853	    const FieldSchema &field,
854	    const core::IndexProvider::Pointer &raw_vector_provider,
855	    std::shared_ptr<FieldSchema> *out_field) {
856	  auto vector_index_params =
857	      std::dynamic_pointer_cast<VectorIndexParams>(field.index_params());
858	  if (!vector_index_params) {
859	    return Status::InvalidArgument("field is not a vector field");
860	  }
861	
862	  auto field_clone = std::make_shared<FieldSchema>(field);
863	
864	  if (vector_index_params->quantize_type() != QuantizeType::RABITQ) {
865	    *out_field = field_clone;
866	    return Status::OK();
867	  }
868	
869	#if !RABITQ_SUPPORTED
870	  (void)raw_vector_provider;
871	  return Status::NotSupported(
872	      "RabitQ is not supported on this platform (Linux x86_64 only)");
873	#else
874	  if (raw_vector_provider == nullptr) {
875	    return Status::InvalidArgument(
876	        "raw_vector_provider is required for RABITQ training");
877	  }
878	
879	  auto rabitq_params = std::dynamic_pointer_cast<HnswRabitqIndexParams>(
880	      vector_index_params->clone());
881	  if (!rabitq_params) {
882	    return Status::InternalError("Expect HnswRabitqIndexParams");
883	  }
884	
885	  auto converter = core::IndexFactory::CreateConverter("RabitqConverter");
886	  if (!converter) {
887	    return Status::NotSupported("RabitqConverter not found");
888	  }
889	  core::IndexMeta index_meta;
890	  index_meta.set_meta(
891	      ProximaEngineHelper::convert_to_engine_data_type(field.data_type())
892	          .value(),
893	      field.dimension());
894	  index_meta.set_metric(core_interface::Index::get_metric_name(
895	                            ProximaEngineHelper::convert_to_engine_metric_type(
896	                                vector_index_params->metric_type())
897	                                .value(),
898	                            false),
899	                        0, ailego::Params{});
900	  ailego::Params converter_params;
901	  converter_params.set(core::PARAM_RABITQ_TOTAL_BITS,
902	                       rabitq_params->total_bits());
903	  converter_params.set(core::PARAM_RABITQ_NUM_CLUSTERS,
904	                       rabitq_params->num_clusters());
905	  converter_params.set(core::PARAM_RABITQ_SAMPLE_COUNT,
906	                       rabitq_params->sample_count());
907	  if (int ret = converter->init(index_meta, converter_params); ret != 0) {
908	    return Status::InternalError("Failed to init rabitq converter:", ret);
909	  }
910	  if (int ret = converter->train(raw_vector_provider); ret != 0) {
911	    return Status::InternalError("Failed to train rabitq converter:", ret);
912	  }
913	  core::IndexReformer::Pointer reformer;
914	  if (int ret = converter->to_reformer(&reformer); ret != 0) {
915	    return Status::InternalError("Failed to to get rabitq reformer:", ret);
916	  }
917	  rabitq_params->set_rabitq_reformer(reformer);
918	  rabitq_params->set_raw_vector_provider(raw_vector_provider);
919	
920	  field_clone->set_index_params(rabitq_params);
921	  *out_field = field_clone;
922	  return Status::OK();
923	#endif
924	}
