991	Status SegmentHelper::ReduceFts(const CollectionSchema::Ptr &schema,
992	                                const std::vector<Segment::Ptr> &input_segments,
993	                                const std::string &output_segment_path,
994	                                const roaring::Roaring &delete_row_id_bitmap,
995	                                std::function<BlockID()> &block_id_generator,
996	                                std::vector<BlockMeta> *output_block_metas) {
997	  if (!schema->has_fts_field()) {
998	    return Status::OK();
999	  }
1000	  if (input_segments.empty()) {
1001	    return Status::OK();
1002	  }
1003	
1004	  auto fts_fields = schema->fts_fields();
1005	
1006	  auto fts_block_id = block_id_generator();
1007	
1008	  // Build the destination FTS RocksDB with the post-dump CF layout:
1009	  // postings + positions per field, plus the shared stat CF.  Side CFs
1010	  // ($TF/$MAX_TF/$DOC_LEN) are skipped — the reducer writes BitPacked
1011	  // directly, matching the immutable-segment shape after
1012	  // convert_postings_to_bitpacked().
1013	  auto dst_fts_path =
1014	      FileHelper::MakeFtsIndexPath(output_segment_path, fts_block_id);
1015	  std::vector<std::string> cf_names;
1016	  std::unordered_map<std::string, std::shared_ptr<rocksdb::MergeOperator>>
1017	      per_cf_merge_ops;
1018	  for (const auto &field : fts_fields) {
1019	    const auto &name = field->name();
1020	    cf_names.push_back(name);
1021	    cf_names.push_back(name + kFtsPositionsSuffix);
1022	    per_cf_merge_ops[name] = std::make_shared<fts::FtsPostingsMerge>();
1023	  }
1024	  cf_names.push_back(kFtsStatCfName);
1025	
1026	  auto dst_ctx = std::make_shared<RocksdbContext>();
1027	  Status s = dst_ctx->create(
1028	      RocksdbContext::Args{dst_fts_path, cf_names, nullptr, per_cf_merge_ops,
1029	                           /*enable_hash_skiplist=*/true});
1030	  if (!s.ok()) {
1031	    LOG_ERROR("ReduceFts: create destination FTS RocksDB failed at [%s]: %s",
1032	              dst_fts_path.c_str(), s.message().c_str());
1033	    return s;
1034	  }
1035	
1036	  // Feed segments in caller's order — matches the scan order
1037	  // delete_row_id_bitmap is keyed by.
1038	  auto *dst_stat_cf = dst_ctx->get_cf(kFtsStatCfName);
1039	  for (const auto &field : fts_fields) {
1040	    const auto &name = field->name();
1041	    auto *dst_postings_cf = dst_ctx->get_cf(name);
1042	    auto *dst_positions_cf = dst_ctx->get_cf(name + kFtsPositionsSuffix);
1043	
1044	    fts::FtsRocksdbReducer reducer;
1045	    auto init_ret = reducer.init(name, dst_ctx.get(), dst_postings_cf,
1046	                                 dst_positions_cf, dst_stat_cf);
1047	    if (!init_ret) {
1048	      auto err = init_ret.error();
1049	      LOG_ERROR("ReduceFts: reducer.init failed. field[%s] err[%s]",
1050	                name.c_str(), err.message().c_str());
1051	      (void)dst_ctx->close();
1052	      return err;
1053	    }
1054	
1055	    for (auto &seg : input_segments) {
1056	      auto src_indexer = seg->get_fts_indexer(name);
1057	      if (!src_indexer) {
1058	        auto err = Status::InternalError(
1059	            "ReduceFts: source segment missing FTS indexer. segment_id=",
1060	            seg->id(), " field=", name);
1061	        LOG_ERROR("%s", err.message().c_str());
1062	        (void)dst_ctx->close();
1063	        return err;
1064	      }
1065	      fts::FtsSegmentStats stats{seg->meta()->min_doc_id(),
1066	                                 seg->meta()->max_doc_id(),
1067	                                 seg->meta()->doc_count()};
1068	      auto feed_ret =
1069	          reducer.feed(stats, src_indexer->ctx(), src_indexer->postings_cf(),
1070	                       src_indexer->positions_cf());
1071	      if (!feed_ret) {
1072	        auto err = feed_ret.error();
1073	        LOG_ERROR("ReduceFts: reducer.feed failed. field[%s] err[%s]",
1074	                  name.c_str(), err.message().c_str());
1075	        (void)dst_ctx->close();
1076	        return err;
1077	      }
1078	    }
1079	
1080	    auto reduce_ret = reducer.reduce(delete_row_id_bitmap);
1081	    if (!reduce_ret) {
1082	      auto err = reduce_ret.error();
1083	      LOG_ERROR("ReduceFts: reducer.reduce failed. field[%s] err[%s]",
1084	                name.c_str(), err.message().c_str());
1085	      (void)dst_ctx->close();
1086	      return err;
1087	    }
1088	    (void)reducer.cleanup();
1089	  }
1090	
1091	  s = dst_ctx->flush();
1092	  if (!s.ok()) {
1093	    LOG_ERROR("ReduceFts: flush destination FTS RocksDB failed: %s",
1094	              s.message().c_str());
1095	    (void)dst_ctx->close();
1096	    return s;
1097	  }
1098	  s = dst_ctx->close();
1099	  if (!s.ok()) {
1100	    LOG_ERROR("ReduceFts: close destination FTS RocksDB failed: %s",
1101	              s.message().c_str());
1102	    return s;
1103	  }
1104	
1105	  BlockMeta fts_block;
1106	  fts_block.set_id(fts_block_id);
1107	  fts_block.set_type(BlockType::FTS_INDEX);
1108	  output_block_metas->push_back(fts_block);
1109	
1110	  return Status::OK();
1111	}
