1118	        &task.output_vector_indexers_, &task.output_quant_vector_indexers_);
1119	  } else {
1120	    return task.input_segment_->create_vector_index(
1121	        task.column_to_build_vector_index_, task.index_params_,
1122	        task.concurrency_, &task.output_segment_meta_,
1123	        &task.output_vector_indexers_, &task.output_quant_vector_indexers_);
1124	  }
1125	}
