160	//! Return 1 if success or -1 if write error
161	int LocalWalFile::write_record(WalRecord &record) {
162	  CHECK_STATUS(opened_, true);
163	
164	  int write_size = 0;
165	  int ret = -1;
166	
167	  std::lock_guard<std::mutex> lock(file_mutex_);
168	  do {
169	    write_size = file_.write((const void *)&record.length_, LENGTH_SIZE);
170	    if (write_size != LENGTH_SIZE) {
171	      WLOG_ERROR("Wal write error. record.length_ error write_size[%d]",
172	                 write_size);
173	      break;
174	    }
175	
176	    write_size = file_.write((const void *)&record.crc_, CRC_SIZE);
177	    if (write_size != CRC_SIZE) {
178	      WLOG_ERROR("Wal write error. record.crc_ error write_size[%d]",
179	                 write_size);
180	      break;
181	    }
182	
183	    write_size =
184	        file_.write((const void *)record.content_.data(), record.length_);
185	    if (write_size != (int)record.length_) {
186	      WLOG_ERROR("Wal write error. record.content_ error write_size[%d]",
187	                 write_size);
188	      break;
189	    }
190	    ret = 1;  // write one record success
191	    docs_count_++;
192	  } while (false);
193	
194	  return ret;
195	}
